                BigDecimal.ONE.subtract(
                    BigDecimal.ONE.divide(denominador, 20, RoundingMode.HALF_EVEN)
                ),
                20,
                RoundingMode.HALF_EVEN
            );

            BigDecimal totalComJuros = parcela.multiply(new BigDecimal(parcelas));
            BigDecimal juros = totalComJuros.subtract(total);

            return arredondar(juros);
        }

        return BigDecimal.ZERO;
    }

    private BigDecimal calcularValorParcela(FormaPagamento forma, BigDecimal total, int parcelas) {
        if (forma == FormaPagamento.CARTAO && parcelas > 3) {
            BigDecimal taxa = CARTAO_JUROS_MENSAL.multiply(new BigDecimal(parcelas - 3));
            BigDecimal umMaisTaxa = BigDecimal.ONE.add(taxa);
            BigDecimal denominador = umMaisTaxa.pow(parcelas).multiply(
                BigDecimal.ONE.add(taxa)
            );
            BigDecimal parcela = total.multiply(taxa).divide(
                BigDecimal.ONE.subtract(
                    BigDecimal.ONE.divide(denominador, 20, RoundingMode.HALF_EVEN)
                ),
                20,
                RoundingMode.HALF_EVEN
            );
            return arredondar(parcela);
        }

        return arredondar(total.divide(new BigDecimal(parcelas), 20, RoundingMode.HALF_EVEN));
    }

    private BigDecimal calcularCredito(BigDecimal subtotal, NivelClube nivel) {
        BigDecimal percentual = new BigDecimal(String.valueOf(nivel.getCreditoPercentual()));
        BigDecimal credito = subtotal.multiply(percentual);
        return arredondar(credito);
    }

    private boolean isBrinde(BigDecimal subtotal, NivelClube nivel) {
        if (nivel != NivelClube.OURO) {
            return false;
        }
        return subtotal.compareTo(VALOR_BRINDE) > 0;
    }

    private boolean isValidCupom(String cupom) {
        return cupom.equals("BEMVINDO10") ||
               cupom.equals("MENOS50") ||
               cupom.equals("FRETEGRATIS") ||
               cupom.equals("LEVE3PAGUE2");
    }

    private BigDecimal arredondar(BigDecimal valor) {
        return valor.setScale(2, RoundingMode.HALF_EVEN);
    }

    public static class CheckoutException extends RuntimeException {
