        itens.add(new ItemCarrinho("Camiseta", 79.90, 2, 0.30));

        CheckoutRequest request = criarRequest(itens, "RETIRADA_LOJA", "LEVE3PAGUE2", "CARTAO", 3, "PRATA", "SUL");
